#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<pair<long long, long long>> iv(n);  // (end, start)
    for (auto& [e, s] : iv) cin >> s >> e;
    sort(iv.begin(), iv.end());
    long long last = -1;
    int count = 0;
    for (const auto& [e, s] : iv)
        if (s >= last) {
            count++;
            last = e;
        }
    cout << count << '\n';
    return 0;
}

